// 贪心解法：能跳2块就跳2块，否则跳1块
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> stones(n);
    for (int i = 0; i < n; ++i) cin >> stones[i];
    int i = 0, ans = 0;
    while (i < n - 1) {
        if (i + 2 < n && stones[i + 2] == 0) i += 2;  // 优先跳2块
        else i += 1;                                   // 否则跳1块
        ++ans;
    }
    cout << ans << "\n";
    return 0;
}
